Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_add_digit_non_null_no_next_success(void) {
    // Setup: create a big_int node with no next_digit
    big_int *digit = add_digit(NULL, '5');
    TEST_ASSERT_NOT_NULL(digit);
    TEST_ASSERT_EQUAL('5', digit->value);
    TEST_ASSERT_NULL(digit->next_digit);
    TEST_ASSERT_NULL(digit->prev_digit);

    // Test: add a new digit to the existing node (digit->next_digit is NULL)
    // This triggers the target path: digit != NULL, digit->next_digit == NULL
    char new_value = '7';
    big_int *new_digit = add_digit(digit, new_value);

    // Assertions
    TEST_ASSERT_NOT_NULL(new_digit);
    TEST_ASSERT_EQUAL('7', new_digit->value);
    TEST_ASSERT_NULL(new_digit->next_digit);
    TEST_ASSERT_EQUAL_PTR(digit, new_digit->prev_digit);
    TEST_ASSERT_EQUAL_PTR(new_digit, digit->next_digit);

    // Cleanup
    helper_free_big_int(digit);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_add_digit_non_null_no_next_success);
    return UNITY_END();
}

