#include "unity.h"
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include "header.h"

// Function declarations
big_int *add_digit(big_int *digit, char value);
char remove_digits(big_int *digit, int n);

// ========== Created - Assertion Operations ==========

// Asserts that a big_int digit has the expected value
void assert_big_int_value(big_int *digit, int expected_value) {
    TEST_ASSERT_NOT_NULL(digit);
    TEST_ASSERT_EQUAL_INT(expected_value, digit->value);
}

// Asserts that a big_int linked list has the expected number of digits
void assert_big_int_digit_count(big_int *digit, int expected_count) {
    int count = 0;
    big_int *current = digit;
    while (current != NULL) {
        count++;
        current = current->next_digit;
    }
    TEST_ASSERT_EQUAL_INT(expected_count, count);
}

// ========== Created - Utility Operations ==========

// Creates a big_int linked list from an array of digit values
big_int* helper_create_big_int(int *values, int size) {
    big_int *root = NULL;
    big_int *current = NULL;
    for (int i = 0; i < size; i++) {
        if (i == 0) {
            root = add_digit(NULL, (char)values[i]);
            current = root;
        } else {
            current = add_digit(current, (char)values[i]);
        }
    }
    return root;
}

// Frees all digits in a big_int linked list
void helper_free_big_int(big_int *digit) {
    // Call remove_digits with N=0 to free all remaining nodes safely
    // This ensures no double-free if remove_digits already freed some nodes
    if (digit != NULL) {
        (void)remove_digits(digit, 0);
    }
}

